INSERT INTO changelog_entries(version,title,summary,content,category,published_at,affected_route,created_at,updated_at) SELECT '2.58.0','Известия без задължителен вход и дневни обобщения по държава','Активирайте публични известия директно или влезте с Google за личните си настройки.','["Известията за избрана държава могат да се активират без профил. Дневното обобщение включва реалния брой новооткрити и отворени процедури.","Входът с Google е отделна възможност. Поканата се възстановява на същата страница, а съществуващият браузърен абонамент се свързва сигурно с профила.","Premium запазва всички настройки и дневните AI отчети, с допълнителен общ лимит на известията за деня.","Запазени са приветствието, показването след 50% скрол и ограничението на автоматичните покани до веднъж за 24 часа."]','fix','2026-09-20','/',datetime('now'),datetime('now') WHERE NOT EXISTS (SELECT 1 FROM changelog_entries WHERE version='2.58.0');
